parameters.jsCode:
// 1. Obtenemos el dato del mensaje original desde un nodo anterior.
// Usar .first() es una buena práctica para asegurar que solo procesas un ítem.
const mensajeOriginal = $input.first().json.data.message.conversation;

// 2. Construimos el objeto JavaScript con la estructura CORRECTA.
// El 'content' está al mismo nivel que 'type', sin el objeto 'data'.
const messageObject = {
  type: "ai",
  content: mensajeOriginal,
  // -------------------------------------------------------------------
  // Estas claves adicionales hacen que tu mensaje sea idéntico a uno
  // generado por el agente, aunque no siempre son estrictamente necesarias.
  additional_kwargs: {},
  tool_calls: [],
  invalid_tool_calls: [],
  response_metadata: {}
  // -------------------------------------------------------------------
};

// 3. Convertimos el objeto a un string JSON para pasarlo al nodo de PostgreSQL.
const jsonParaPostgres = JSON.stringify(messageObject);

// 4. Devolvemos los datos que usará el siguiente nodo (PostgreSQL).
return [
  {
    json: {
      messageJsonString: jsonParaPostgres,
      // Pasamos también el session_id para usarlo en la consulta SQL.
      sessionId: $input.first().json.data.key.remoteJid
    }
  }
];

